-- Import initial du calendrier Fortnite Cups vers Supabase
-- Ce script conserve chaque objet cup complet dans competitions.details.
-- Il crée une compétition par région lorsqu'un tournoi a plusieurs horaires régionaux.
-- Réexécutable : les compétitions et sessions sont mises à jour, pas dupliquées.
begin;

create unique index if not exists sessions_competition_numero_unique
  on public.sessions (competition_id, numero_session);

