eload-victory-cup-event-3-round-1-10-12","name":"Solo Reload Victory Cup – Événement 3, Round 1","kind":"Victory Cup","mode":"Reload · Solos","rules":"Jusqu’à 8 parties en 2 h. Rang Diamant minimum à partir de l’événement 3. Le classement du Round 1 détermine les qualifiés pour le Round 2.","sc":"game","date":"2026-10-12","officialUrl":"https://www.fortnite.com/competitive/events/S42_ReloadSoloVictoryCup?region=EU","auditStatus":"official-verified","times":{"EU":["2026-10-12T17:00:00Z","2026-10-12T19:00:00Z"],"NAC":["2026-10-12T04:00:00Z","2026-10-12T06:00:00Z"],"NAW":["2026-10-12T08:00:00Z","2026-10-12T10:00:00Z"]},"prize":"100 $ par Victory Royale au Round 2.","qual":["Accès : rang Diamant minimum en Reload classé pour l’événement 3."],"adv":{"EU":"Top 960","NAC":"Top 480","_":"Top 192"},"thr":{"th":[[1,1,6],[2,3,4],[4,10,3],[11,15,2],[16,30,1]],"e":2,"m":8},"thrNote":"Barème vérifié sur Fortnite Tracker : victoire +6, Top 2–3 +4 chacun, Top 4–10 +3 chacun, Top 11–15 +2 chacun, Top 16–30 +1 chacun, élimination +2. Jusqu’à 8 parties en Round 1.","score":[["Victoire royale","+6"],["Top 2 à Top 3","+4 par palier"],["Top 4 à Top 10","+3 par palier"],["Top 11 à Top 15","+2 par palier"],["Top 16 à Top 30","+1 par palier"],["Chaque élimination","+2"]],"scoreNote":"Barème relevé dans les sources de tournoi consultées ; consulte les liens officiels pour confirmer les éventuelles différences par région/session.","poster":"https://cdn2.unrealengine.com/fneco-35-00-consolevictorycup-comp-in-game-tab-800x800-rockerpunk-800x800-791783a7a571.jpg","timeSource":"Fortnite Tracker EU : Event 3, 12/10/2026 17:00–19:00 / 20:00–20:45"},{"id":"solo-reload-victory-cup-event-3-round-2-10-12","name":"Solo Reload Victory Cup – Événement 3, Round 2","kind":"Victory Cup","mode":"Reload · Solos","rules":"Finale courte de 3 parties. Chaque Victory Royale attribue 100 $ au joueur gagnant.","sc":"game","date":"2026-10-12","officialUrl":"https://www.fortnite.com/competitive/events/S42_ReloadSoloVictoryCup?region=EU","auditStatus":"official-verified","times":{"EU":["2026-10-12T20:00:00Z","2026-10-12T20:45:00Z"],"NAC":["2026-10-12T07:00:00Z","2026-10-12T07:45:00Z"],"NAW":["2026-10-12T11:00:00Z","2026-10-12T11:45:00Z"]},"prize":"100 $ par Victory Royale.","score":[["Round 2","3 parties ; chaque Victory Royale vaut 100 $"]],"scoreNote":"Barème relevé dans les sources de tournoi consultées ; consulte les liens officiels pour confirmer les éventuelles différences par région/session.","poster":"https://cdn2.unrealengine.com/fneco-35-00-consolevictorycup-comp-in-game-tab-800x800-rockerpunk-800x800-791783a7a571.jpg","timeSource":"Fortnite Tracker EU : Event 3, 12/10/2026 17:00–19:00 / 20:00–20:45"}]$cups$::jsonb) as cup
),
expanded as (
  select s.cup, r.region
  from source_data s
  cross join lateral (
    select jsonb_object_keys(s.cup->'times') as region
    where jsonb_typeof(s.cup->'times') = 'object'
      and s.cup->'times' <> '{}'::jsonb
    union all
    select 'EU'
    where coalesce(s.cup->'times', '{}'::jsonb) = '{}'::jsonb
  ) r
),
upserted as (
  insert into public.competitions
    (nom, region, mode, format, source, url_source, identifiant_externe, statut, details)
  select
    coalesce(cup->>'name', cup->>'id', 'Compétition Fortnite'),
    region,
    cup->>'mode',
    cup->>'kind',
    'fortnite-cups',
    cup->>'officialUrl',
    cup->>'id',
    case
      when coalesce(cup->>'end', cup->>'date', '2999-12-31') < current_date::text then 'terminee'
      else 'a_venir'
    end,
    cup
  from expanded
  on conflict (source, region, identifiant_externe)
    where identifiant_externe is not null
  do update set
    nom = excluded.nom,
    mode = excluded.mode,
    format = excluded.format,
    url_source = excluded.url_source,
    statut = excluded.statut,
    details = excluded.details,
    mis_a_jour_le = now()
  returning id, region, details
)
insert into public.sessions
  (competition_id, numero_session, nom_session, debut, fin, details)
select
  id,
  1,
  coalesce(details->>'name', 'Session') || ' · ' || region,
  (details->'times'->region->>0)::timestamptz,
  (details->'times'->region->>1)::timestamptz,
  jsonb_build_object('import', 'fortnite-cups', 'region', region)
from upserted
where jsonb_typeof(details->'times'->region) = 'array'
  and jsonb_array_length(details->'times'->region) >= 2
  and details->'times'->region->>0 is not null
  and details->'times'->region->>1 is not null
on conflict (competition_id, numero_session)
do update set
  nom_session = excluded.nom_session,
  debut = excluded.debut,
  fin = excluded.fin,
  details = excluded.details;

commit;

-- Vérification après exécution :
select count(*) as competitions_importees from public.competitions
where source = 'fortnite-cups';
select count(*) as sessions_importees from public.sessions
where details->>'import' = 'fortnite-cups';
